import forge.ai.*;
import forge.game.*;import forge.game.card.*;import forge.game.combat.*;import forge.game.phase.*;import forge.game.player.*;import forge.game.zone.*;import forge.game.trigger.*;import forge.game.ability.*;import forge.game.spellability.*;import forge.game.keyword.*;
import java.util.*;import org.testng.Assert;
public class PureRulesGate extends AITest {
 int checks;void pass(String s){checks++;System.out.println("PASS "+s);}
 void ready(Game g){for(Player p:g.getPlayers())fillLibrary(p,20);g.getAction().checkStateEffects(true);g.getTriggerHandler().resetActiveTriggers();}
 void drain(Game g){g.getTriggerHandler().runWaitingTriggers();g.getStack().addAllTriggeredAbilitiesToStack();int guard=0;while(!g.getStack().isEmpty()){if(guard++>30)throw new AssertionError("trigger loop");System.out.println("Resolving: "+g.getStack().peekAbility());g.getStack().resolveStack();g.getTriggerHandler().runWaitingTriggers();g.getStack().addAllTriggeredAbilitiesToStack();}}
 long dragons(Player p){return p.getCreaturesInPlay().stream().filter(c->c.isToken()&&c.getType().hasSubtype("Dragon")&&c.getType().hasSubtype("Spirit")).count();}
 void damage(Game g,Card source,Player target){Map<AbilityKey,Object> m=AbilityKey.newMap();m.put(AbilityKey.IsCombatDamage,true);m.put(AbilityKey.DamageTarget,target);m.put(AbilityKey.DamageMap,Map.of(source,1));g.getTriggerHandler().runTrigger(TriggerType.DamageDoneOnce,m,false);drain(g);}
 void ggs(String type,boolean fresh){Game g=initAndCreateGame();Player ai=g.getPlayers().get(1),opp=g.getPlayers().get(0);addCard("Goro-Goro and Satoru",ai);Card body=addCard("Changeling Outcast",ai);if(type!=null)addCard("Roaming Throne",ai).setChosenType(type);ready(g);body.setTurnInZone(g.getPhaseHandler().getTurn()-(fresh?0:1));System.out.println("Before damage dragons="+dragons(ai)+" stack="+g.getStack().size());damage(g,body,opp);System.out.println("After damage creatures="+ai.getCreaturesInPlay());Assert.assertEquals(dragons(ai),fresh?(type==null||type.equals("Dragon")?1L:2L):0L);pass("GGS fresh="+fresh+" Throne="+type);}
 void forge(){Game g=initAndCreateGame();Player ai=g.getPlayers().get(1);addCard("Urabrask's Forge",ai);ready(g);for(int combat=1;combat<=2;combat++){g.getPhaseHandler().devModeSet(PhaseType.COMBAT_BEGIN,ai,false);g.getTriggerHandler().resetActiveTriggers();g.getTriggerHandler().runTrigger(TriggerType.Phase,AbilityKey.mapFromPlayer(ai),false);drain(g);var horrors=ai.getCreaturesInPlay();Assert.assertEquals(horrors.size(),combat);Assert.assertEquals(horrors.get(combat-1).getNetPower(),combat);Assert.assertTrue(horrors.get(combat-1).hasKeyword(Keyword.HASTE));Assert.assertTrue(horrors.get(combat-1).hasKeyword(Keyword.TRAMPLE));pass("Forge combat "+combat+" creates growing haste token");}}
 void krenko(){Game g=initAndCreateGame();Player ai=g.getPlayers().get(1),opp=g.getPlayers().get(0);Card k=addCard("Krenko, Tin Street Kingpin",ai);ready(g);g.getPhaseHandler().devModeSet(PhaseType.COMBAT_DECLARE_ATTACKERS,ai,false);Combat c=new Combat(ai);c.addAttacker(k,opp);g.getPhaseHandler().setCombat(c);Map<AbilityKey,Object> m=AbilityKey.newMap();m.put(AbilityKey.Attacker,k);m.put(AbilityKey.Attacked,opp);m.put(AbilityKey.DefendingPlayer,opp);m.put(AbilityKey.Defenders,List.of(opp));m.put(AbilityKey.OtherAttackers,List.of());g.getTriggerHandler().resetActiveTriggers();g.getTriggerHandler().runTrigger(TriggerType.Attacks,m,false);drain(g);var bodies=ai.getCreaturesInPlay().stream().filter(x->x.getId()!=k.getId()).toList();Assert.assertEquals(bodies.size(),2);for(Card b:bodies){Assert.assertFalse(c.isAttacking(b));Assert.assertFalse(b.isTapped());}pass("Krenko Goblins enter untapped and not attacking");}
 void assault(){Game g=initAndCreateGame();Player ai=g.getPlayers().get(1);Card a=addCard("Aggravated Assault",ai);for(int i=0;i<5;i++)addCard("Mountain",ai);ready(g);SpellAbility s=a.getSpellAbilities().stream().filter(x->x.getApi()==ApiType.UntapAll).findFirst().orElseThrow();s.setActivatingPlayer(ai);Assert.assertTrue(ComputerUtil.handlePlayingSpellAbility(ai,s,null));drain(g);Assert.assertTrue(g.getPhaseHandler().hasExtraPhaseAfter(PhaseType.MAIN1,PhaseType.COMBAT_BEGIN));pass("paid Assault schedules actual extra combat");}
 void shadow(){Game g=initAndCreateGame();Player ai=g.getPlayers().get(1),opp=g.getPlayers().get(0);System.setProperty("forge.ai.ggsPilotPlayer",ai.getName());addCard("Goro-Goro and Satoru",ai);Card carrier=addCard("Changeling Outcast",ai),other=addCard("Goldspan Dragon",ai),shadow=addCardToZone("Thousand-Faced Shadow",ai,ZoneType.Hand);for(int i=0;i<4;i++)addCard("Island",ai);ready(g);g.getPhaseHandler().devModeSet(PhaseType.COMBAT_DECLARE_BLOCKERS,ai,false);Combat c=new Combat(ai);carrier.setSickness(false);other.setSickness(false);c.addAttacker(carrier,opp);c.addAttacker(other,opp);c.setBlocked(carrier,false);c.setBlocked(other,false);g.getPhaseHandler().setCombat(c);SpellAbility sa=shadow.getSpellAbilities().stream().filter(s->s.isNinjutsu()).findFirst().orElseThrow();sa.setActivatingPlayer(ai);Assert.assertTrue(ComputerUtil.handlePlayingSpellAbility(ai,sa,null));drain(g);Assert.assertTrue(ai.getCreaturesInPlay().stream().anyMatch(x->x.getName().equals("Thousand-Faced Shadow")));Assert.assertTrue(ai.getCreaturesInPlay().stream().filter(x->x.isToken()).anyMatch(x->c.isAttacking(x)));pass("actual ninjutsu/Shadow creates tapped attacking copy");}
 public static void main(String[]args){PureRulesGate t=new PureRulesGate();t.initializeModel();t.ggs(null,true);t.ggs(null,false);t.ggs("Human",true);t.ggs("Goblin",true);t.ggs("Dragon",true);t.forge();t.krenko();t.assault();t.shadow();System.out.println("Checks passed: "+t.checks);System.exit(0);}
}
